output:
variable "project" {
  type    = string
  default = "acme"
}

resource "aws_s3_bucket" "data" {
  bucket = "${var.project}-${terraform.workspace}-data"

  tags = {
    Workspace = terraform.workspace
  }
}

locals {
  env_config = {
    default = {
      instance_type = "t3.micro"
      desired_size  = 1
    }
    staging = {
      instance_type = "t3.small"
      desired_size  = 2
    }
    production = {
      instance_type = "m5.large"
      desired_size  = 4
    }
  }

  config = lookup(local.env_config, terraform.workspace, local.env_config["default"])
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = local.config.instance_type

  tags = {
    Name = "app-${terraform.workspace}"
  }
}

variable "ami_id" {
  type = string
}

locals {
  regions = {
    default    = "us-east-1"
    europe     = "eu-west-1"
    asia       = "ap-southeast-1"
  }
}

provider "aws" {
  region = lookup(local.regions, terraform.workspace, "us-east-1")
}

resource "aws_sqs_queue" "events" {
  name = "events-${terraform.workspace}"
}

import {
  to = aws_s3_bucket.legacy
  id = "acme-legacy-bucket"
}

resource "aws_s3_bucket" "legacy" {
  bucket = "acme-legacy-bucket"

  tags = {
    Imported = "true"
  }
}

import {
  to = aws_instance.web
  id = "i-0abc1234def567890"
}

resource "aws_instance" "web" {
  ami           = var.ami_id
  instance_type = "t3.small"

  tags = {
    Name = "web-imported"
  }
}

variable "ami_id" {
  type = string
}

moved {
  from = aws_sqs_queue.legacy_jobs
  to   = aws_sqs_queue.jobs
}

resource "aws_sqs_queue" "jobs" {
  name = "background-jobs"
}

moved {
  from = module.app_v1
  to   = module.app
}

module "app" {
  source = "./modules/app"

  name    = "acme-app"
  env     = "staging"
}

locals {
  sizing = {
    default    = { count = 1, type = "t3.micro" }
    staging    = { count = 2, type = "t3.small" }
    production = { count = 4, type = "t3.medium" }
  }

  current = lookup(local.sizing, terraform.workspace, local.sizing["default"])
}

resource "aws_instance" "worker" {
  count         = local.current.count
  ami           = var.ami_id
  instance_type = local.current.type

  tags = {
    Name = "worker-${terraform.workspace}-${count.index}"
  }
}

variable "ami_id" {
  type = string
}

import {
  to = aws_iam_role.deploy
  id = "legacy-deploy-role"
}

resource "aws_iam_role" "deploy" {
  name = "legacy-deploy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = { Service = "codedeploy.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

import {
  to = aws_dynamodb_table.sessions
  id = "sessions-prod"
}

resource "aws_dynamodb_table" "sessions" {
  name         = "sessions-prod"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "session_id"

  attribute {
    name = "session_id"
    type = "S"
  }
}

data "terraform_remote_state" "network" {
  backend = "s3"

  config = {
    bucket = "acme-terraform-state"
    key    = "network/${terraform.workspace}/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_sqs_queue" "app" {
  name = "app-events-${terraform.workspace}"

  tags = {
    VpcId = data.terraform_remote_state.network.outputs.vpc_id
  }
}

import {
  to = aws_s3_bucket.logs
  id = "acme-manual-logs"
}

import {
  to = aws_s3_bucket.audit
  id = "acme-manual-audit"
}

resource "aws_s3_bucket" "logs" {
  bucket = "acme-manual-logs"
}

resource "aws_s3_bucket" "audit" {
  bucket = "acme-manual-audit"
}

variable "workspace_tags" {
  type = map(map(string))
  default = {
    default    = { Owner = "platform", CostCenter = "dev" }
    staging    = { Owner = "platform", CostCenter = "staging" }
    production = { Owner = "sre", CostCenter = "prod" }
  }
}

resource "aws_sqs_queue" "events" {
  name = "events-${terraform.workspace}"
  tags = lookup(var.workspace_tags, terraform.workspace, {})
}

moved {
  from = module.network_v1[0]
  to   = module.network[0]
}

module "network" {
  count  = 1
  source = "./modules/v2-network"

  name       = "shared"
  cidr_block = "10.20.0.0/16"
}

import {
  to = aws_vpc.main
  id = "vpc-0abc1234def567890"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.30.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "imported-vpc"
  }
}

import {
  to = aws_cloudwatch_log_group.app
  id = "/acme/production/app"
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "/acme/production/app"
  retention_in_days = 30
}

resource "aws_sqs_queue" "jobs" {
  name = "jobs-${terraform.workspace}"
}

output "queue_url" {
  value       = aws_sqs_queue.jobs.url
  description = "URL of the ${terraform.workspace} job queue"
}

output "workspace" {
  value = terraform.workspace
}

moved {
  from = aws_s3_bucket.data_old
  to   = aws_s3_bucket.data
}

import {
  to = aws_s3_bucket.shared
  id = "acme-shared-artifacts"
}

resource "aws_s3_bucket" "data" {
  bucket = "acme-data-${terraform.workspace}"
}

resource "aws_s3_bucket" "shared" {
  bucket = "acme-shared-artifacts"
}

resource "aws_sqs_queue" "non_default_only" {
  count = terraform.workspace == "default" ? 0 : 1

  name = "workspace-queue-${terraform.workspace}"
}

import {
  to = aws_security_group.app
  id = "sg-0abc1234def567890"
}

resource "aws_security_group" "app" {
  name   = "app-sg"
  vpc_id = var.vpc_id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  tags = {
    Name = "app-sg"
  }
}

variable "vpc_id" {
  type = string
}
